/**
 * Generated by `createservice user.ResetUserService --type mutations`
 */

/**
 * Reset user mutation removes phone, email and password from user, making it impossible to use this user.
 *
 * Mutation also sets name to "Deleted User" and do not set deletedAt.
 * Reason for this is the fact that if we soft-delete user, then we are about to face a lot of "user is null" kind of errors in unpredictable places.
 * Name is changed so we can distinguish reset users.
 *
 * Telegram uses the same approach: if user is deleted, then all his messages and other content are available, but his name is now "Deleted user"
 *
 * Primary use cases:
 * 1. QA Wants to test SMS services, but dont want to get multiple phone numbers
 * 2. User wants to remove all his data from our system.
 */

const { GQLError, GQLErrorCode: { BAD_USER_INPUT, FORBIDDEN } } = require('@open-condo/keystone/errors')
const { GQLCustomSchema, getById, getByCondition, find } = require('@open-condo/keystone/schema')

const { removeOrphansRecurrentPaymentContexts } = require('@condo/domains/acquiring/tasks')
const { DV_VERSION_MISMATCH } = require('@condo/domains/common/constants/errors')
const { OrganizationEmployee, OrganizationEmployeeRequest } = require('@condo/domains/organization/utils/serverSchema')
const access = require('@condo/domains/user/access/ResetUserService')
const { DELETED_USER_NAME } = require('@condo/domains/user/constants')
const { User, UserSudoToken } = require('@condo/domains/user/utils/serverSchema')
const { detectTokenTypeSafely, TOKEN_TYPES } = require('@condo/domains/user/utils/tokens')

const { USER_NOT_FOUND, CANNOT_RESET_ADMIN_USER, INVALID_TOKEN, UNSUPPORTED_TOKEN, TOKEN_NOT_FOUND } = require('../constants/errors')
const { UserExternalIdentity } = require('../utils/serverSchema')


const ERRORS = {
    DV_VERSION_MISMATCH: {
        mutation: 'resetUser',
        variable: ['data', 'dv'],
        code: BAD_USER_INPUT,
        type: DV_VERSION_MISMATCH,
        message: 'Unsupported value for dv',
    },
    USER_NOT_FOUND: {
        mutation: 'resetUser',
        variable: ['data', 'user', 'id'],
        code: BAD_USER_INPUT,
        type: USER_NOT_FOUND,
        message: 'Could not find User by provided id',
    },
    CANNOT_RESET_ADMIN_USER: {
        mutation: 'resetUser',
        variable: ['data', 'user', 'id'],
        code: FORBIDDEN,
        type: CANNOT_RESET_ADMIN_USER,
        message: 'You cannot reset admin user',
    },
    INVALID_TOKEN: {
        mutation: 'resetUser',
        variable: ['data', 'token'],
        code: BAD_USER_INPUT,
        type: INVALID_TOKEN,
        message: 'Invalid token',
        messageForUser: 'api.user.resetUser.INVALID_TOKEN',
    },
    UNSUPPORTED_TOKEN: {
        mutation: 'resetUser',
        variable: ['data', 'token'],
        code: BAD_USER_INPUT,
        type: UNSUPPORTED_TOKEN,
        message: 'Unsupported token',
        messageForUser: 'api.user.resetUser.UNSUPPORTED_TOKEN',
    },
    TOKEN_NOT_FOUND: {
        mutation: 'resetUser',
        variable: ['data', 'token'],
        code: BAD_USER_INPUT,
        type: TOKEN_NOT_FOUND,
        message: 'Unable to find non-expired UserSudoToken by specified token',
        messageForUser: 'api.user.resetUser.TOKEN_NOT_FOUND',
    },
    OPERATION_FAILED: {
        mutation: 'resetUser',
        code: BAD_USER_INPUT,
        type: 'OPERATION_FAILED',
        message: 'The operation failed',
        messageForUser: 'api.user.resetUser.OPERATION_FAILED',
    },
}

const ResetUserService = new GQLCustomSchema('ResetUserService', {
    types: [
        {
            access: true,
            type: 'input ResetUserInput { dv: Int! sender: SenderFieldInput! user: UserWhereUniqueInput!, saveName: Boolean, token: String }',
        },
        {
            access: true,
            type: 'type ResetUserOutput { status: String! }',
        },
    ],

    mutations: [
        {
            access: access.canResetUser,
            schema: 'resetUser(data: ResetUserInput!): ResetUserOutput',
            doc: {
                summary: 'Used for cleaning existing user to avoid utilizing every time new phone and email',
                errors: ERRORS,
            },
            resolver: async (parent, args, context) => {
                const { data } = args
                const { dv, sender, user, saveName, token } = data
                if (!user.id) throw new Error('resetUser(): no user.id')

                if (dv !== 1) {
                    throw new GQLError(ERRORS.DV_VERSION_MISMATCH, context)
                }

                const userEntity = await getById('User', user.id)
                if (!userEntity) {
                    throw new GQLError(ERRORS.USER_NOT_FOUND, context)
                }

                if (userEntity.isAdmin) {
                    throw new GQLError(ERRORS.CANNOT_RESET_ADMIN_USER, context)
                }

                let sudoToken = null

                // A user can only reset themselves with a sudo token
                if (user.id === context?.authedItem?.id) {
                    const { error: tokenError, tokenType } = detectTokenTypeSafely(token)
                    if (tokenError) {
                        throw new GQLError({ ...ERRORS.INVALID_TOKEN, data: { error: tokenError } }, context)
                    }

                    if (tokenType !== TOKEN_TYPES.SUDO) {
                        throw new GQLError(ERRORS.UNSUPPORTED_TOKEN, context)
                    }

                    sudoToken = await getByCondition('UserSudoToken', {
                        token,
                        expiresAt_gte: new Date().toISOString(),
                        remainingUses_gt: 0,
                        deletedAt: null,
                    })

                    if (!sudoToken) throw new GQLError(ERRORS.TOKEN_NOT_FOUND, context)
                    if (sudoToken.user !== user.id) throw new GQLError(ERRORS.OPERATION_FAILED, context)
                }

                const newUserData = {
                    dv: 1,
                    sender,
                    phone: null,
                    email: null,
                    password: null,
                    isPhoneVerified: false,
                    isEmailVerified: false,
                    isAdmin: false,
                    isSupport: false,
                }

                if (!saveName) {
                    newUserData.name = DELETED_USER_NAME
                }

                await User.update(context, user.id, newUserData)

                if (sudoToken) {
                    await UserSudoToken.update(context, sudoToken.id, {
                        dv: 1, sender,
                        remainingUses: sudoToken.remainingUses - 1,
                    })
                }

                const employees = await find('OrganizationEmployee', { user: { id: user.id }, deletedAt: null })
                for (const employee of employees) {
                    await OrganizationEmployee.softDelete(context, employee.id, 'id', { dv: 1, sender })
                }

                const notProcessedEmployeeRequests = await find('OrganizationEmployeeRequest', {
                    user: { id: user.id },
                    deletedAt: null,
                })
                for (const request of notProcessedEmployeeRequests) {
                    await OrganizationEmployeeRequest.softDelete(context, request.id, 'id', { dv: 1, sender })
                }

                const accordingUserExternalIdentity = await UserExternalIdentity.getAll(context, {
                    user: {
                        id: user.id,
                    },
                    deletedAt: null,
                })

                for (const externalIdentity of accordingUserExternalIdentity) {
                    await UserExternalIdentity.softDelete(context, externalIdentity.id, 'id', { dv: 1, sender })
                }

                // remove RecurrentPaymentContext
                await removeOrphansRecurrentPaymentContexts.delay({
                    userId: user.id,
                    dv,
                    sender,
                })

                return { status: 'ok' }
            },
        },
    ],

})

module.exports = {
    ResetUserService,
}
